def mailto_href(slug, market, q_plain):
    subj = urllib.parse.quote("Show me a creator answer [%s|%s]" % (slug, market))
    body = urllib.parse.quote(
        "Yes please \u2014 I'd like to see the 20-second creator demo.\n\n"
        "My brand: \nMy website: \n\n"
        "-- do not edit below, it tells the team what to build --\n"
        "question: %s\ncategory: %s\nmarket: %s\n" % (q_plain, slug, market))
    return "mailto:%s?subject=%s&amp;body=%s" % (MAILTO, subj, body)

